fun {R} [CommRing R] I f g hI hfg =>
  let e := FormalSpectrum.awayAwayLocEquiv f g hfg;
  let φ := e.toRingEquiv.toRingHom;
  let ψ := e.symm.toRingEquiv.toRingHom;
  let Kg := Ideal.map (algebraMap R (Localization.Away g)) I;
  let KC :=
    Ideal.map
      (algebraMap (Localization.Away f)
        (Localization.Away ((algebraMap R (Localization.Away f)) g)))
      (Ideal.map (algebraMap R (Localization.Away f)) I);
  have hKgFG := ⋯;
  have hKCFG := ⋯;
  have hA := ⋯;
  have hB := ⋯;
  RingEquiv.ofRingHom (AdicCompletion.mapCompletion φ hA hKCFG)
    (AdicCompletion.mapCompletion ψ hB hKgFG) ⋯ ⋯

